function reorganizeString(s) {
  const chars = [...s];
  const used = new Array(chars.length).fill(false);
  const out = [];
  const build = () => {                      // try every arrangement, one letter at a time
    if (out.length === chars.length) return true;
    for (let i = 0; i < chars.length; i++) {
      if (used[i] || out[out.length - 1] === chars[i]) continue;   // no two equal neighbours
      used[i] = true;
      out.push(chars[i]);
      if (build()) return true;
      used[i] = false;                       // stuck later on: undo and try the next letter
      out.pop();
    }
    return false;
  };
  return build() ? out.join("") : "";
}

