    return build(chars, new boolean[chars.length], out) ? out.toString() : "";
}

boolean build(char[] chars, boolean[] used, StringBuilder out) {   // one letter at a time
    if (out.length() == chars.length) return true;
    for (int i = 0; i < chars.length; i++) {
        if (used[i] || (out.length() > 0 && out.charAt(out.length() - 1) == chars[i])) continue;
        used[i] = true;
        out.append(chars[i]);
        if (build(chars, used, out)) return true;
        used[i] = false;                     // stuck later on: undo and try the next letter
        out.deleteCharAt(out.length() - 1);
    }
    return false;
}

bool build(const string& s, vector<bool>& used, string& out) {   // one letter at a time
    if (out.size() == s.size()) return true;
    for (int i = 0; i < (int)s.size(); i++) {
        if (used[i] || (!out.empty() && out.back() == s[i])) continue;   // no two equal neighbours
        used[i] = true;
        out.push_back(s[i]);
        if (build(s, used, out)) return true;
        used[i] = false;                     // stuck later on: undo and try the next letter
        out.pop_back();
    }
    return false;
}

string reorganizeString(string s) {
    vector<bool> used(s.size(), false);
    string out;
    return build(s, used, out) ? out : "";
}

function reorganizeString(s) {
  const count = new Map();
  for (const ch of s) count.set(ch, (count.get(ch) ?? 0) + 1);
  const heap = Heap.from([...count], (a, b) => b[1] - a[1]);   // [letter, count]: most left first
  let out = "";
  let held = null;                           // the letter just used: it must sit out one turn
  while (heap.size() > 0) {
    const [ch, c] = heap.pop();              // the most frequent letter that isn't the last one
    out += ch;
    if (held) heap.push(held);               // the previous letter may be used again
    held = c > 1 ? [ch, c - 1] : null;
  }
  return held ? "" : out;                    // a letter still waiting had nowhere to go
}

