    int[] count = new int[26];
    for (char ch : s.toCharArray()) count[ch - 'a']++;
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(b[1], a[1]));   // {letter, count}
    for (int i = 0; i < 26; i++) if (count[i] > 0) heap.offer(new int[]{i, count[i]});
    StringBuilder out = new StringBuilder();
    int[] held = null;                       // the letter just used: it must sit out one turn
    while (!heap.isEmpty()) {
        int[] top = heap.poll();             // the most frequent letter that isn't the last one
        out.append((char) ('a' + top[0]));
        if (held != null) heap.offer(held);  // the previous letter may be used again
        held = top[1] > 1 ? new int[]{top[0], top[1] - 1} : null;
    }
    return held != null ? "" : out.toString();   // a letter still waiting had nowhere to go
}

