function reorganizeString(s) {
  const count = new Map();
  for (const ch of s) count.set(ch, (count.get(ch) ?? 0) + 1);
  let top = s[0];
  for (const [ch, c] of count) if (c > count.get(top)) top = ch;   // the most frequent letter
  if (count.get(top) > Math.ceil(s.length / 2)) return "";        // too many copies to keep apart
  const out = new Array(s.length);
  let i = 0;
  const place = (ch) => {
    for (let c = count.get(ch); c > 0; c--) {
      if (i >= s.length) i = 1;              // even slots are full: continue on the odd ones
      out[i] = ch;
      i += 2;
    }
  };
  place(top);                                // the most frequent letter goes first
  for (const ch of count.keys()) if (ch !== top) place(ch);
  return out.join("");
}

from collections import Counter

def reorganize_string(s):
    count = Counter(s)
    top = max(count, key=count.get)          # the most frequent letter
    if count[top] > (len(s) + 1) // 2:
        return ""                            # too many copies to keep apart
    out = [""] * len(s)
    i = 0
    for ch in [top] + [c for c in count if c != top]:   # the most frequent letter goes first
        for _ in range(count[ch]):
            if i >= len(s):
                i = 1                        # even slots are full: continue on the odd ones
            out[i] = ch
            i += 2
    return "".join(out)

