    int n = s.length();
    int[] count = new int[26];
    for (char ch : s.toCharArray()) count[ch - 'a']++;
    int top = 0;
    for (int k = 1; k < 26; k++) if (count[k] > count[top]) top = k;   // the most frequent letter
    if (count[top] > (n + 1) / 2) return "";                           // too many copies to keep apart
    char[] out = new char[n];
    int i = 0;
    for (; count[top] > 0; count[top]--, i += 2) out[i] = (char) ('a' + top);   // it goes first
    for (int k = 0; k < 26; k++) {
        for (; count[k] > 0; count[k]--, i += 2) {
            if (i >= n) i = 1;               // even slots are full: continue on the odd ones
            out[i] = (char) ('a' + k);
        }
    }
    return new String(out);
}

